// Applies the approved geography split (CLAUDE.md 3): populates admin_region
// from the value-level triage, and rewrites state_province_county_island to
// hold only the traveller-facing area.
//
// One-time record of a reviewed session, same pattern as the
// apply-award-review-* scripts (24/25). Do not edit this file's lists for a
// future round — copy the pattern.
//
//   Dry-run by default.  --confirm to write.  --only <id> to scope.
//
// Idempotent, but note WHY that needed care. Rows are looked up by their
// PRE-split value and the apply overwrites exactly that value, so after a run
// the key no longer resolves for any row whose area changed (130 of 537 here).
// Worse, some rows re-resolve to the WRONG entry: Mandarin Oriental Cortina
// ends up with area "Dolomites", which matches the Italy||Dolomites entry whose
// admin is South Tyrol — correct for Alta Badia, wrong for Cortina, which is
// Veneto. A re-run would have silently corrupted it.
//
// So the rollback record, not the current field values, is the authority on
// what has already been applied: a row whose stored pair matches its last
// applied target is skipped before any lookup happens.
// The rollback record APPENDS rather than overwrites (40) — a second run only
// reports rows it actually changed, and writing fresh would discard the first
// run's record.
//
// Usage:
//   DIRECTUS_URL=... DIRECTUS_TOKEN=... node scripts/hotels/geo-2026/apply-geo-split-2026-08-31.mjs
//   ... --confirm
import fs from "fs/promises";
import path from "path";

const DIRECTUS_URL = process.env.DIRECTUS_URL?.replace(/\/+$/, "");
const DIRECTUS_TOKEN = process.env.DIRECTUS_TOKEN;
if (!DIRECTUS_URL || !DIRECTUS_TOKEN) throw new Error("Missing DIRECTUS_URL or DIRECTUS_TOKEN");

const CONFIRM = process.argv.includes("--confirm");
const ONLY = (() => {
  const i = process.argv.indexOf("--only");
  return i === -1 ? null : Number(process.argv[i + 1]);
})();

const DIR = "scripts/hotels/geo-2026";
const ROLLBACK = `${DIR}/apply-geo-split-2026-08-31-rollback.json`;

// ---------------------------------------------------------------------------
// Per-hotel exceptions for the 18 "split" rows.
//
// A split row is one where a single current value covers hotels that need
// different answers. Applying the value-level proposal blindly would write a
// KNOWN-WRONG value to specific hotels — Splendido is in Portofino (Liguria),
// not on the Amalfi Coast; Chable Yucatan really is Yucatan while the rest of
// that value is Quintana Roo. Every entry below is the answer named in the
// note that was reviewed and approved for that value.
//
// `admin`/`area` are absent where the value-level answer is already correct
// for that hotel. area: null means clear it.
// ---------------------------------------------------------------------------
const PER_HOTEL = {
  // Italy :: Amalfi Coast — two Portofino properties, wrong coast entirely.
  1428: { admin: "Liguria", area: "Italian Riviera" }, // Splendido
  1478: { admin: "Liguria", area: "Italian Riviera" }, // Splendido Mare

  // Italy :: Tuscany — Florence is a major city, so no traveller area.
  3018: { area: null }, // Collegio alla Querce

  // Italy :: Veneto
  2020: { area: "Dolomites" }, // Mandarin Oriental Cortina
  3004: { area: null }, // Airelles Palladio, Venice

  // Mexico :: Yucatan — only Chochola is genuinely Yucatan; Cancun is its own city.
  1629: { admin: "Yucatán", area: null }, // Chablé Yucatán
  1639: { area: null }, // NIZUC, Cancun

  // South Africa :: Kruger National Park — the reserve spans two provinces.
  1052: { admin: "Limpopo" }, // Royal Malewane, Hoedspruit
  3014: { admin: "Limpopo" }, // &Beyond Ngala

  // Thailand :: Phuket — Koh Yao Noi is Phang Nga, not Phuket.
  1217: { admin: "Phang Nga Province", area: "Phang Nga Bay" }, // Six Senses Yao Noi

  // Australia :: New South Wales
  1794: { area: "Lord Howe Island" }, // Capella Lodge

  // Canada :: British Columbia
  1621: { area: "Whistler" }, // Fairmont Chateau Whistler

  // United Kingdom :: Scotland
  1507: { area: "Perthshire" }, // Gleneagles
  1508: { area: "Scottish Highlands" }, // Inverlochy Castle
  1509: { area: "Fife" }, // Old Course, St Andrews
  1511: { area: "Scottish Highlands" }, // The Torridon

  // USA :: California
  1659: { area: "Napa Valley" }, // Auberge du Soleil
  1662: { area: "Carmel Valley" }, // Bernardus Lodge
  1676: { area: "Napa Valley" }, // Four Seasons Napa Valley
  1706: { area: "Big Sur" }, // Post Ranch Inn
  1710: { area: "Napa Valley" }, // Stanly Ranch
  1752: { area: "Lake Tahoe" }, // Ritz-Carlton Lake Tahoe

  // USA :: New York
  1771: { area: "Hudson Valley" }, // Wildflower Farms

  // USA :: Hawaii — the island is the traveller area.
  1652: { area: "Kauai" }, // 1 Hotel Hanalei Bay
  1677: { area: "Big Island" }, // Four Seasons Hualalai
  1679: { area: "Lanai" }, // Sensei Lanai
  1680: { area: "Lanai" }, // Four Seasons Lanai
  1685: { area: "Oahu" }, // Halekulani
  1693: { area: "Big Island" }, // Mauna Lani
  1750: { area: "Maui" }, // Ritz-Carlton Kapalua
  2032: { area: "Maui" }, // Four Seasons Maui at Wailea

  // USA :: Nevada
  1689: { area: "Lake Tahoe" }, // Edgewood Tahoe

  // USA :: Colorado
  1701: { area: "Vail Valley" }, // Park Hyatt Beaver Creek
  1731: { area: "Aspen" }, // The Little Nell
  1745: { area: "Vail Valley" }, // Ritz-Carlton Bachelor Gulch

  // USA :: Massachusetts
  1770: { area: "Cape Cod" }, // Wequassett

  // USA :: Montana
  1694: { area: "Big Sky" }, // Montage Big Sky

  // USA :: Utah
  1759: { area: "Park City" }, // St. Regis Deer Valley

  // USA :: Georgia (was the "Giorgia" misspelling)
  1719: { area: "Sea Island" }, // The Cloister at Sea Island
};

// ---------------------------------------------------------------------------

async function api(pathname, { method = "GET", body } = {}) {
  const res = await fetch(`${DIRECTUS_URL}${pathname}`, {
    method,
    headers: {
      Authorization: `Bearer ${DIRECTUS_TOKEN}`,
      "Content-Type": "application/json",
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  const data = await res.json().catch(() => null);
  if (!res.ok) throw new Error(`HTTP ${res.status} ${pathname}: ${JSON.stringify(data)}`);
  return data;
}

const clean = (v) => (v ?? "").trim();
const norm = (v) => (clean(v) === "" ? null : clean(v));

async function main() {
  const triage = JSON.parse(await fs.readFile(`${DIR}/geo-triage-2026-08-31.json`, "utf8"));
  const plan = new Map(triage.values.map((v) => [v.k, v]));

  // What a previous run already wrote, id -> its target pair.
  let alreadyApplied = new Map();
  try {
    const prior = JSON.parse(await fs.readFile(ROLLBACK, "utf8"));
    alreadyApplied = new Map(prior.map((c) => [c.id, c.to]));
  } catch {
    alreadyApplied = new Map();
  }

  const { data: hotels } = await api(
    "/items/hotels?fields=id,hotel_name,country,city,state_province_county_island,admin_region&limit=-1"
  );

  const changes = [];
  const unplanned = [];

  for (const h of hotels) {
    if (ONLY !== null && Number(h.id) !== ONLY) continue;

    const current = clean(h.state_province_county_island);
    const nowAdminEarly = norm(h.admin_region);

    // Settled by a previous run — check before the lookup, because the lookup
    // key is the value this pass overwrites (see the header).
    const done = alreadyApplied.get(Number(h.id));
    if (
      done &&
      nowAdminEarly === done.admin_region &&
      norm(h.state_province_county_island) === done.state_province_county_island
    ) {
      continue;
    }

    if (!current) continue; // blanks are step 4, not this pass

    const key = `${clean(h.country)}||${current}`;
    const entry = plan.get(key);
    if (!entry) {
      unplanned.push({ id: h.id, key });
      continue;
    }

    const ex = PER_HOTEL[Number(h.id)] ?? {};
    const targetAdmin = norm("admin" in ex ? ex.admin : entry.admin);
    const targetArea = norm("area" in ex ? ex.area : entry.area);

    const nowAdmin = norm(h.admin_region);
    const nowArea = norm(h.state_province_county_island);

    if (targetAdmin === nowAdmin && targetArea === nowArea) continue;

    changes.push({
      id: Number(h.id),
      hotel_name: clean(h.hotel_name),
      country: clean(h.country),
      city: clean(h.city),
      status: entry.status,
      exception: Object.keys(ex).length > 0,
      from: { admin_region: nowAdmin, state_province_county_island: nowArea },
      to: { admin_region: targetAdmin, state_province_county_island: targetArea },
    });
  }

  // A value in Directus with no triage entry would silently keep its old,
  // unsplit meaning — loud failure is the only safe response.
  if (unplanned.length) {
    console.error(`\nABORT: ${unplanned.length} hotel(s) carry a value with no triage entry:`);
    for (const u of unplanned.slice(0, 20)) console.error(`  ${u.id}  ${u.key}`);
    process.exit(1);
  }

  console.log(`${hotels.length} hotels scanned | ${changes.length} to change`);
  console.log(`  of which per-hotel exceptions: ${changes.filter((c) => c.exception).length}`);
  const clearing = changes.filter((c) => c.to.state_province_county_island === null).length;
  console.log(`  clearing the traveller area (major city / admin-only value): ${clearing}`);

  for (const c of changes) {
    const a = `${c.from.admin_region ?? "-"} -> ${c.to.admin_region ?? "-"}`;
    const s = `${c.from.state_province_county_island ?? "-"} -> ${c.to.state_province_county_island ?? "-"}`;
    console.log(
      `  ${String(c.id).padEnd(5)} ${c.hotel_name.slice(0, 40).padEnd(41)}` +
        `admin[${a}]  area[${s}]${c.exception ? "  *exception" : ""}`
    );
  }

  if (!CONFIRM) {
    console.log("\nDRY RUN — nothing written. Re-run with --confirm to apply.");
    return;
  }

  let ok = 0;
  const applied = [];
  for (const c of changes) {
    // Re-read immediately before writing so a concurrent edit isn't clobbered
    // and a re-run of an already-applied row is a no-op rather than a rewrite.
    const { data: fresh } = await api(
      `/items/hotels/${c.id}?fields=id,state_province_county_island,admin_region`
    );
    const freshAdmin = norm(fresh.admin_region);
    const freshArea = norm(fresh.state_province_county_island);

    if (freshAdmin === c.to.admin_region && freshArea === c.to.state_province_county_island) {
      console.log(`  skip ${c.id} (already at target)`);
      continue;
    }
    if (freshArea !== c.from.state_province_county_island) {
      console.error(
        `  SKIP ${c.id}: stored area changed since the scan ` +
          `(${JSON.stringify(freshArea)} != ${JSON.stringify(c.from.state_province_county_island)})`
      );
      continue;
    }

    await api(`/items/hotels/${c.id}`, {
      method: "PATCH",
      body: {
        admin_region: c.to.admin_region,
        state_province_county_island: c.to.state_province_county_island,
      },
    });
    applied.push({ ...c, applied_at: new Date().toISOString() });
    ok += 1;
  }

  let previous = [];
  try {
    previous = JSON.parse(await fs.readFile(ROLLBACK, "utf8"));
  } catch {
    previous = [];
  }
  await fs.mkdir(path.dirname(ROLLBACK), { recursive: true });
  await fs.writeFile(ROLLBACK, JSON.stringify([...previous, ...applied], null, 2));

  console.log(`\nApplied ${ok}. Rollback record now holds ${previous.length + applied.length} entries: ${ROLLBACK}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
